-- The sheet's review SLA: a REVIEW claim whose review day (the sheet's today when it went to REVIEW) plus
-- this many days is before the sheet's today is late for review. None means none. Not dated.
ALTER TABLE sheet ADD COLUMN review_sla INTEGER CHECK (review_sla >= 0);
@RequestMapping("/api/sheets")
public class SheetController {

    /** A sheet as the screen shows it: its today, its clerk limit (two decimals; none for no limit) and
     *  its floor (two decimals), its terms (days), its late percent (two decimals) and its policy date (none: the sheet's today) and its period numbering from-date (none: off), the terms of each grade that has its own, and its cap (two decimals; none for no cap), and its proof threshold (two decimals; none for no threshold), and its note threshold (two decimals; none for no threshold), and its review threshold (two decimals; none for no threshold), and its grace days (none: off), and whether it is archived, and its entry date (none: off), and the number of its last settle batch (none before the first), and its pot (two decimals; none for no pot), and its parent sheet's id (none for no parent), and its fiscal start month (1 to 12), and its alert threshold (two decimals; none for off), and its rounding mode (half-up or half-even; none: by the policy date), and its escalation gap (days; none: off), and its review SLA (days; none: none), and its proof kinds (comma separated; none: none), and its default grade (none: A), and its mid and high score thresholds (none: no bands), and whether its score log is on.
     *  The dated settings show the value in force on the sheet's today; every value recorded for them is in
     *  settings. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<SettingView> settings, String proofThreshold, Map<String, String> permissions, Integer graceDays,
            boolean archived, String noteThreshold, LocalDate entryDate, Integer lastSettleBatch, String pot,
            String parent, int fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, Integer escalateAfter,
            Integer reviewSla, String proofKinds, String defaultGrade, Integer scoreMid, Integer scoreHigh, boolean scoreLog) {

        static SheetView of(Sheet sheet) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(SettingView::of).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions(), sheet.getGraceDays(), sheet.isArchived(),
                    sheet.getNoteThreshold() == null ? null : sheet.getNoteThreshold().toPlainString(),
                    sheet.getEntryDate(), sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch(),
                    sheet.getPot() == null ? null : sheet.getPot().toPlainString(), sheet.getParent(),
                    sheet.getFiscalStartMonth(),
                    sheet.getAlertThreshold() == null ? null : sheet.getAlertThreshold().toPlainString(),
                    sheet.getRoundingMode(),
                    sheet.getReviewThreshold() == null ? null : sheet.getReviewThreshold().toPlainString(),
    }

    /** The sheet's score log switch: on, or blank (missing) for off. */
    public record ScoreLogRequest(@Pattern(regexp = "on|") String value) {
    }

    /** The sheet's review SLA in days; missing means none. */
    public record ReviewSlaRequest(@Min(0) @Max(36500) Integer reviewSla) {
    }

    /** The sheet's proof kinds, comma separated (receipt or photo); missing or blank means none. */
    public record ProofKindsRequest(
            @Size(max = 200) @Pattern(regexp = "\\s*((receipt|photo)(\\s*,\\s*(receipt|photo))*)?\\s*") String proofKinds) {
    }

    /** The sheet's default grade, one of the grades; missing or blank means A. */

    /** Switch the sheet's score log on or off. */
    @PutMapping("/{id}/settings/score-log")
    public SheetView setScoreLog(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ScoreLogRequest request) {
        return SheetView.of(service.setScoreLog(id.trim(), user.trim(), "on".equals(request.value())));
    }

    /** Change the sheet's review SLA. */
    @PutMapping("/{id}/settings/review-sla")
    public SheetView setReviewSla(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid ReviewSlaRequest request) {
        return SheetView.of(service.setReviewSla(id.trim(), user.trim(), request.reviewSla()));
    }

    /** Change the sheet's proof kinds. */
    @PutMapping("/{id}/settings/proof-kinds")
    public SheetView setProofKinds(@PathVariable @NotBlank @Size(max = 200) String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
    /** Switch the sheet's score log on or off. Not dated. */
    @Transactional
    public Sheet setScoreLog(String id, String user, boolean on) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setScoreLog(on);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=score-log value=" + (on ? "on" : ""));
        return sheet;
    }

    /** Change the sheet's review SLA in days (none: none). Not dated. */
    @Transactional
    public Sheet setReviewSla(String id, String user, Integer days) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        sheet.setReviewSla(days);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=review-sla value="
                + (days == null ? "" : days.toString()));
        return sheet;
    }

    /** Change the sheet's proof kinds (a comma separated list of receipt or photo; blank: none). Not dated. */
    @Transactional
    public Sheet setProofKinds(String id, String user, String kinds) {
        Sheet sheet = sheets.findForUpdateById(id).orElseThrow(SheetNotFoundException::new);
        String list = kinds == null ? "" : String.join(",", kinds.trim().split("\\s*,\\s*"));
        sheet.setProofKinds(list.isEmpty() ? null : list);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=proof-kinds value=" + list);
     *  being left. Not dated. */
    @Column(name = "score_log")
    private boolean scoreLog;

    /** The review SLA: a REVIEW claim whose review day (the sheet's today when it went to REVIEW) plus these
     *  many days is before the sheet's today is late for review; none means none. Not dated. */
    @Column(name = "review_sla")
    private Integer reviewSla;

    /** The proof kinds, comma separated: a claim above the proof threshold needs at least one proof of each
     *  before it can be settled or approved; none means none. Not dated. */
    }

    public void setScoreLog(boolean scoreLog) {
        this.scoreLog = scoreLog;
    }

    public Integer getReviewSla() {
        return reviewSla;
    }

    public void setReviewSla(Integer reviewSla) {
        this.reviewSla = reviewSla;
    }

    public String getProofKinds() {
        return proofKinds;

