        for (Line line : lines) {
            Optional<Claim> match = match(before, line, line.date() != null ? line.date() : entry);
            if (match.isPresent() && !taken.add(match.get().getId())) {
                throw refused(line.number(), "its claim is already updated by an earlier line.");
            }
            matched.add(match);
